import Ajv from 'ajv';
import type {ErrorObject, ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({strict: false, validateFormats: false});
  private readonly validators = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private getValidator(schema: ToolDefinition['inputSchema']): ValidateFunction {
    const cached = this.validators.get(schema);
    if (cached) return cached;
    const validator = this.ajv.compile(schema);
    this.validators.set(schema, validator);
    return validator;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        validator = this.ajv.compile(resolved.inputSchema);
      } catch (error) {
        throw new Error(`Invalid inputSchema for tool '${resolved.name}': ${String(error)}`, {cause: error});
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates tool input before execution; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const validator = tool.validator ?? this.getValidator(definition.inputSchema);
    if (!validator(input)) {
      const failures = (validator.errors ?? []).map(error => this.describeValidationError(error));
      log.warn('tool', 'input rejected', {name, failures});
      return {result: `Invalid tool input: ${failures.join('; ')}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }

  private describeValidationError(error: ErrorObject): string {
    const path = error.instancePath || '/';
    if (error.keyword === 'required' || error.keyword === 'additionalProperties') {
      const property = error.keyword === 'required' ? error.params.missingProperty : error.params.additionalProperty;
      const propertyPath = `${path === '/' ? '' : path}/${String(property)}`;
      return error.keyword === 'required'
        ? `${propertyPath} is required`
        : `${propertyPath} failed additionalProperties constraint`;
    }
    if (error.keyword === 'type') {
      return `${path} must be ${String(error.params.type)}`;
    }
    return `${path} failed ${error.keyword} constraint`;
  }
}
import {ToolRegistry} from './registry.js';
import Ajv from 'ajv';
import {jest} from '@jest/globals';

describe('ToolRegistry schema compilation', () => {
  it('throws at register time for an invalid static schema and names the tool [specs/hal-engine-tool-input-validation/spec.md#6]', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_weather',
          description: 'Broken weather tool',
          inputSchema: {type: 'object', properties: {location: {type: 'not-a-json-schema-type'}}},
        },
        async () => 'unused'
      )
    ).toThrow(/broken_weather/);
  });

  it('names an explicitly forbidden extra property without revealing its value [specs/hal-engine-tool-input-validation/spec.md#4]', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'ok');
    registry.register(
      {
        name: 'weather',
        description: 'Weather',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, additionalProperties: false},
      },
      executor
    );

    const result = (await registry.execute('weather', {location: 'Paris', secret: 'private-identifier'})).result;
    expect({
      namesPath: result.includes('/secret'),
      namesConstraint: result.includes('additionalProperties'),
      leaksValue: result.includes('private-identifier'),
      executorCalls: executor.mock.calls.length,
    }).toEqual({namesPath: true, namesConstraint: true, leaksValue: false, executorCalls: 0});
  });
});

describe('ToolRegistry dynamic schemas', () => {
  it('validates each resolved schema and reuses validators for the same schema object [specs/hal-engine-tool-input-validation/spec.md#8]', async () => {
    const registry = new ToolRegistry();
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    const locationSchema = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    const unitSchema = {
      type: 'object',
      properties: {unit: {type: 'string'}},
      required: ['unit'],
    };
    let currentSchema: typeof locationSchema | typeof unitSchema = locationSchema;
    const executor = jest.fn(async () => 'ok');
    registry.register(() => ({name: 'weather', description: 'Weather', inputSchema: currentSchema}), executor);

    try {
      const firstResult = (await registry.execute('weather', {})).result;
      currentSchema = unitSchema;
      const secondResult = (await registry.execute('weather', {})).result;
      const thirdResult = (await registry.execute('weather', {})).result;
      expect({
        firstNamesLocation: firstResult.includes('location'),
        secondNamesUnit: secondResult.includes('unit'),
        thirdNamesUnit: thirdResult.includes('unit'),
        executorCalls: executor.mock.calls.length,
        compileCalls: compile.mock.calls.length,
      }).toEqual({
        firstNamesLocation: true,
        secondNamesUnit: true,
        thirdNamesUnit: true,
        executorCalls: 0,
        compileCalls: 2,
      });
    } finally {
      compile.mockRestore();
    }
  });
});
